import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

a, b = map(int, input().split())
primes = [str(x) for x in range(a, b + 1) if is_prime(x)]
if primes:
    print(' '.join(primes))
else:
    print('KHONG CO')
